header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, interactive-widget=resizes-content"><title>Finans · Güncelleme</title><link rel="stylesheet" href="assets/fonts.css"><link rel="stylesheet" href="assets/design-tokens.css"><style>body{margin:0;background:#f5f7f8;color:#202c39;font:var(--text-body)/1.5 Inter,system-ui,sans-serif;font-synthesis:none}main{max-width:620px;margin:clamp(20px,8vh,80px) auto;padding:var(--panel-padding);background:white;border:1px solid #dde3e8;border-radius:var(--radius-panel);box-sizing:border-box}h1{font-size:var(--text-page);font-weight:600;line-height:1.3}button,a{font:inherit}button{padding:12px 20px;min-height:var(--control-size);border:0;border-radius:var(--radius-control);background:#087f8c;color:white;cursor:pointer}button:disabled{opacity:.6;cursor:not-allowed}button:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid #087f8c;outline-offset:3px}a{color:#087f8c}#result{white-space:pre-wrap;overflow-wrap:anywhere}nav{display:flex;flex-wrap:wrap;gap:20px;margin-top:22px}@media(max-width:760px){main{margin:16px}h1{font-size:var(--text-page-mobile)}}</style></head><body><main><h1>Finans güncellemesi</h1><p>Bu ekran veritabanını günceller. Uygulama dosyalarını indirmez veya yüklemez. Yönetici hesabı ve mevcut şifresi korunur. İşlemden önce sunucuda özel bir veritabanı yedeği oluşturulur. Güncelleme sırasında kayıt girişi kapatılır.</p><p>Yeni sürümü kurmak için Hosting ZIP içeriğini doğrudan sitenize yükleyin (tam pakette hosting/ klasörünün içeriğini kullanın); mevcut api/config.php dosyanızı koruyun. Ardından uygulamaya dönüp sayfayı yenileyin.</p><p>Dosyaları yüklemeden önceki site yedeğinizi de saklayın. Diğer açık uygulama sekmelerini kapatın. Bu ekran yalnız yöneticilere açıktır.</p><label style="display:flex;gap:10px;align-items:flex-start;margin:18px 0"><input type="checkbox" id="demo"><span>Mevcut cari, hesap, kart ve işlem kayıtlarını silip kapsamlı demo verilerini oluştur. Yönetici hesabı ve şifresi korunur.</span></label><p id="status" role="status">Sürüm kontrol ediliyor…</p><button id="run" hidden disabled>Veritabanını güncelle</button><button id="seed" hidden style="margin-left:8px;background:#edf1f3;color:#202c39">Demo verilerini yenile</button><p id="result" role="status" aria-live="polite"></p><nav><a href="./">Uygulamaya dön / giriş yap</a><a id="backup" hidden href="api/index.php?action=update_backup">Güncelleme öncesi yedeği indir</a></nav></main><script>
let csrf='';const status=document.getElementById('status'),run=document.getElementById('run'),result=document.getElementById('result');
async function call(action,body){const r=await fetch('api/index.php?action='+action,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'İşlem tamamlanamadı.');return d;}
async function check(){run.disabled=true;run.hidden=true;try{const s=await call('session');csrf=s.csrf;const u=await call('update_status');const target=Number(u.target),version=Number(u.version);if(!Number.isInteger(target)||!Number.isInteger(version))throw Error('Veritabanı sürümü doğrulanamadı.');const pending=version<target;status.textContent=pending?'Veritabanı güncellemesi gerekiyor: şema '+version+' → '+target+'.':version===target?'Veritabanı güncel (şema '+version+'). Bu paket için veritabanı işlemi gerekmiyor. Dosyaları yüklediyseniz uygulamaya dönebilirsiniz.':'Veritabanı şeması ('+version+') bu paketin hedefinden ('+target+') daha yeni. Eski paketle veritabanı güncellemesi yapılmaz.';run.disabled=!pending;run.hidden=!pending;document.getElementById('seed').hidden=version!==target;document.getElementById('backup').hidden=!u.backupReady;}catch(e){status.textContent=e.message;document.getElementById('seed').hidden=true;}}
run.onclick=async()=>{run.disabled=true;result.textContent='Yedek alınıyor ve güncelleme uygulanıyor. Bu sekmeyi kapatmayın.';try{const d=await call('update_apply',{});if(document.getElementById('demo').checked){const key=crypto.randomUUID();await call('demo_seed',{requestId:key});result.textContent=d.message+' Demo verileri hazırlandı; yönetici girişiniz korundu.';}else result.textContent=d.message;await check();}catch(e){result.textContent=e.message;await check();}};document.getElementById('seed').onclick=async()=>{if(!document.getElementById('demo').checked){result.textContent='Demo temizleme seçeneğini işaretleyin.';return;}const btn=document.getElementById('seed');btn.disabled=true;run.disabled=true;try{await call('demo_seed',{requestId:crypto.randomUUID()});result.textContent='Demo verileri yenilendi. Yedi aylık kapsamlı demo hazır; yönetici hesabı ve şifresi korundu.';}catch(e){result.textContent=e.message;}finally{btn.disabled=false;await check();}};check();
</script></body></html>
